from typing import Optional, List, Any, Dict
from pydantic import BaseModel
from motor.motor_asyncio import AsyncIOMotorDatabase
from core.database.repository import MongoRepository


class AIAdvisoryRecord(BaseModel):
    """Encapsulates advice results, images analysis, and summaries generated by AI providers."""
    id: str
    guild_id: int
    type: str  # "moderation", "investigation", "security", "ocr", "translation", "ticket"
    target_id: Optional[int] = None
    input_data: str
    output_data: Dict[str, Any]
    timestamp: float


class RecommendationRepository(MongoRepository):
    """Asynchronous Repository managing Yuna's historical AI advisory outcomes and recommendations."""

    def __init__(self, db: AsyncIOMotorDatabase) -> None:
        super().__init__(db, "ai_recommendations")

    async def save_advisory_record(self, record: AIAdvisoryRecord, session: Optional[Any] = None) -> None:
        doc = {
            "id": record.id,
            "guild_id": record.guild_id,
            "type": record.type,
            "target_id": record.target_id,
            "timestamp": record.timestamp,
            "payload": record.model_dump()
        }
        await self.collection.replace_one({"id": record.id}, doc, upsert=True, session=session)

    async def get_by_id(self, record_id: str, session: Optional[Any] = None) -> Optional[AIAdvisoryRecord]:
        doc = await self.collection.find_one({"id": record_id}, session=session)
        if not doc:
            return None
        return AIAdvisoryRecord(**doc["payload"])

    async def list_by_target(self, guild_id: int, target_id: int, session: Optional[Any] = None) -> List[AIAdvisoryRecord]:
        cursor = self.collection.find({"guild_id": guild_id, "target_id": target_id}, session=session).sort("timestamp", -1)
        docs = await cursor.to_list(length=100)
        return [AIAdvisoryRecord(**doc["payload"]) for doc in docs]

    async def list_by_type(self, guild_id: int, type_str: str, session: Optional[Any] = None) -> List[AIAdvisoryRecord]:
        cursor = self.collection.find({"guild_id": guild_id, "type": type_str}, session=session).sort("timestamp", -1)
        docs = await cursor.to_list(length=100)
        return [AIAdvisoryRecord(**doc["payload"]) for doc in docs]

    async def purge_older_than(self, timestamp: float, session: Optional[Any] = None) -> None:
        await self.collection.delete_many({"timestamp": {"$lt": timestamp}}, session=session)
